using Microsoft.AspNetCore.Mvc;using SlowCoffee.Application.DTOs;using SlowCoffee.Application.Interfaces;
namespace SlowCoffee.Api.Controllers;[ApiController][Route("api/pedidos")]public class PedidosController(IPedidoService s):ControllerBase{[HttpGet]public async Task<ActionResult> Get()=>Ok(await s.ListarAsync());[HttpGet("{id:int}")]public async Task<ActionResult> Get(int id)=>await s.ObterAsync(id) is { } x?Ok(x):NotFound();[HttpPost]public async Task<ActionResult> Post(PedidoCreateDto d){try{var x=await s.CriarAsync(d);return CreatedAtAction(nameof(Get),new{id=x.Id},x);}catch(KeyNotFoundException e){return NotFound(new{message=e.Message});}catch(InvalidOperationException e){return Conflict(new{message=e.Message});}catch(ArgumentException e){return BadRequest(new{message=e.Message});}}[HttpPatch("{id:int}/status")]public async Task<ActionResult> Status(int id,[FromBody]StatusRequest d)=>await s.AtualizarStatusAsync(id,d.Status)?NoContent():BadRequest(new{message="Pedido ou status inválido."});public record StatusRequest(string Status);}
